// Text with names in it (tracks, cars, drivers, setups): the words around the name are translated, the name kept.
// [regular expression source, replacement]. Used by i18n.js when a sentence isn't in the dictionary.
(() => {
  const D = () => window.GRID_DE || {};
  const tr = text => {
    const d = D();
    if (d[text] !== undefined) return d[text];
    const numbers = [];
    const key = text.replace(/\d+(?:[.:,]\d+)*/g, m => (numbers.push(m), "{#}"));
    if (d[key] === undefined) return text;
    let i = 0;
    return d[key].replace(/\{#\}/g, () => numbers[i++] ?? "");
  };
  const sentences = text => text.trim() ? text.trim().split(/(?<=[.!?])\s+/).map(s => (/[A-Za-z]{2}/.test(s) ? tr(s) : s)).join(" ") : "";
  const SESSION = { Race: "Rennen", Practice: "Training", Qualify: "Qualifying", "Lone Qualify": "Qualifying", "Open Qualify": "Qualifying", Warmup: "Warm-up", "Offline Testing": "Testfahrt", Session: "Session", Testing: "Testfahrt" };
  const AREA = { braking: "Bremsen", "corner exit": "Kurvenausgang", "apex speed": "Scheitelpunkt-Tempo", coasting: "Rollen", "exit speed": "Ausgangsgeschwindigkeit", line: "Linie" };
  const AREA_TITLE = { Braking: "Bremsen", "Corner exit": "Kurvenausgang", "Apex speed": "Scheitelpunkt-Tempo", Coasting: "Rollen", "Exit speed": "Ausgangsgeschwindigkeit", Line: "Linie", "Keep it up": "Weiter so" };
  const corner = name => name.replace(/\b(?:Turn|Corner) (\S+)/g, "Kurve $1");
  // Talkback answers built from parts.
  const SETTING = { "brake bias": "die Bremsbalance", "front anti-roll bar": "den vorderen Stabilisator", "rear anti-roll bar": "den hinteren Stabilisator",
    "rear wing": "den Heckflügel", "front wing": "den Frontflügel", "front ride height": "die vordere Fahrhöhe", "rear ride height": "die hintere Fahrhöhe",
    "front springs": "die vorderen Federn", "rear springs": "die hinteren Federn", "front bump (compression) damping": "die vordere Druckstufe",
    "rear bump (compression) damping": "die hintere Druckstufe", "front camber": "den vorderen Sturz", "traction control": "die Traktionskontrolle", abs: "das ABS",
    "throttle map": "das Gas-Mapping", "engine braking": "die Motorbremse", "diff preload": "die Differenzial-Vorspannung", "tyre pressures": "die Reifendrücke" };
  const VERB = { raise: "erhöhen", lower: "verringern", reduce: "verringern", "smooth out": "weicher stellen" };
  const garageItem = item => {
    const m = item.match(/^(?:(raise|lower|reduce|smooth out) the (.+?)|make the (.+?) more negative)(?:, it's on (.+))?$/i);
    if (!m) return item;
    const label = (m[2] || m[3]).toLowerCase();
    return `${SETTING[label] || label} ${m[3] ? "negativer stellen" : VERB[m[1].toLowerCase()]}${m[4] ? `, steht auf ${m[4].replace(/\bclicks?\b/, "Klicks").replace(/\bdeg\b/, "Grad")}` : ""}`;
  };
  const IN_CAR = { "brake bias": "Bremsbalance", abs: "ABS", "traction control": "Traktionskontrolle", "tc slip": "TC-Schlupf", "engine map": "Motor-Mapping",
    "fuel mix": "Gemisch", "engine braking": "Motorbremse", "front bar": "vorderer Stabi", "rear bar": "hinterer Stabi" };
  const FLAG = { yellow: "Gelb", "waving yellow": "geschwenkte Gelbe", caution: "Caution", debris: "Trümmer", blue: "Blau", black: "Schwarz", meatball: "Schwarz-Orange",
    white: "Weiß", checkered: "Zielflagge", red: "Rot", green: "Grün", crossed: "gekreuzte Flaggen" };
  const WARNING = { "water temperature": "Wassertemperatur", "oil temperature": "Öltemperatur", "oil pressure": "Öldruck", "fuel pressure": "Spritdruck", "engine stalled": "Motor abgewürgt" };
  const CORNER = { "left front": "vorne links", "right front": "vorne rechts", "left rear": "hinten links", "right rear": "hinten rechts", lf: "vorne links", rf: "vorne rechts", lr: "hinten links", rr: "hinten rechts" };
  const timeWords = text => text.replace(/(\d+) tenths?/, "$1 Zehntel").replace(/([\d.]+) seconds/, "$1 Sekunden");
  const layer = name => (window.gridLang ? window.gridLang.t(name) : name); // a paint layer's name ("Yellow area")
  const PAINT_COLOURS = "Black|White|Silver|Grey|Red|Brown|Orange|Gold|Yellow|Green|Teal|Navy|Blue|Purple|Pink";
  const AREA_COLOUR = { Black: "Schwarzer", White: "Weißer", Silver: "Silberner", Grey: "Grauer", Red: "Roter", Brown: "Brauner", Orange: "Oranger", Gold: "Goldener",
    Yellow: "Gelber", Green: "Grüner", Teal: "Petrolfarbener", Navy: "Marineblauer", Blue: "Blauer", Purple: "Lila", Pink: "Pinker" };
  const TALK_PATTERNS = [
    [String.raw`^In the garage, try one of these: (.+)\.$`, (m, list) => `Probier in der Garage eins davon: ${list.split(", or ").map(garageItem).join(", oder ")}.`],
    [String.raw`^(?:(?:[Bb]rake bias|ABS|[Tt]raction control|TC slip|[Ee]ngine map|[Ff]uel mix|[Ee]ngine braking|[Ff]ront bar|[Rr]ear bar) [\d.]+(?:, )?)+\.$`, m =>
      `${m.slice(0, -1).split(", ").map(part => part.replace(/^(.+) ([\d.]+)$/, (x, name, value) => `${IN_CAR[name.toLowerCase()] || name} ${value}`)).join(", ")}.`],
    [String.raw`^Starting pressures: (.+)\.$`, (m, list) => `Startdrücke: ${list.split(", ").map(part => part.replace(/^(.+?) (\d.*)$/, (x, where, value) => `${CORNER[where] || where} ${value}`)).join(", ")}.`],
    [String.raw`^(\d+) cars? on pit road right now(?:: (.+))?\.$`, (m, n, list) => `${n === "1" ? "1 Auto" : `${n} Autos`} gerade in der Boxengasse${list ? `: ${list.replace(/\bcar /g, "Auto ")}` : ""}.`],
    [String.raw`^([A-Za-z ]+(?:, [a-z ]+)*) flag\.$`, (m, list) => `Flagge: ${list.split(", ").map(name => FLAG[name.toLowerCase()] || name).join(", ")}.`],
    [String.raw`^Track's (dry|mostly dry|very lightly wet|lightly wet|moderately wet|very wet|extremely wet|unknown)( and it's raining)?\.$`, (m, level, rain) => `Die Strecke ist ${tr(level)}${rain ? " und es regnet" : ""}.`],
    [String.raw`^Warning light: (.+)\.$`, (m, list) => `Warnleuchte: ${list.split(" and ").map(name => WARNING[name] || name).join(" und ")}.`],
    [String.raw`^Copy, (.+)\.$`, (m, rest) => { const t = tr(`Copy, ${rest}.`); return t === `Copy, ${rest}.` ? `Verstanden, ${tr(rest.charAt(0).toUpperCase() + rest.slice(1) + ".").replace(/\.$/, "")}.` : t; }],
    [String.raw`^(.+) is fastest here, best ([\d:.]+) over (\d+) laps?\.$`, (m, setup, best, laps) => `${setup} ist hier am schnellsten, Bestzeit ${best} über ${laps} ${laps === "1" ? "Runde" : "Runden"}.`],
    [String.raw`^(.+) is (\d+ tenths?|[\d.]+ seconds) slower\.$`, (m, setup, gap) => `${setup} ist ${timeWords(gap)} langsamer.`],
    [String.raw`^(.+) is the most consistent\.$`, (m, setup) => `${setup} ist am konstantesten.`],
    [String.raw`^You're on (.+?)(, with changes you haven't saved)?\.$`, (m, setup, changed) => `Du fährst ${setup}${changed ? ", mit ungespeicherten Änderungen" : ""}.`],
    [String.raw`^(.+) is next, swap at the next stop\.$`, (m, name) => `Als Nächstes fährt ${name}, Wechsel beim nächsten Stopp.`]
  ];
  window.GRID_DE_PATTERNS = [
    ...TALK_PATTERNS,
    // Phone pit wall and team hub (before "... is next." below).
    [String.raw`^Driver change at this stop: (.+) is next\.$`, "Fahrerwechsel bei diesem Stopp: als Nächstes fährt $1."],
    [String.raw`^Sent: “(.*)”$`, "Gesendet: „$1“"],
    [String.raw`^(.+)\. Your car is the big dot\. Cars in the pits are faded\.$`, "$1. Dein Auto ist der große Punkt. Autos in der Box sind blass."],
    [String.raw`^Automatic pit fuel: (.+)\.$`, "Automatisches Boxen-Tanken: $1."],
    [String.raw`^Tread left \(inside/middle/outside %\): (.+)\. Measured when you were last in the pits\.$`, "Restprofil (innen/Mitte/außen %): $1. Gemessen bei deinem letzten Boxenbesuch."],
    [String.raw`^On (.+) tyres, (\d+) laps? old\.$`, (m, compound, laps) => `Auf ${compound}-Reifen, ${laps} ${laps === "1" ? "Runde" : "Runden"} alt.`],
    [String.raw`^On (.+) tyres\.$`, "Auf $1-Reifen."],
    [String.raw`^Last measured: (.+)\.$`, "Zuletzt gemessen: $1."],
    [String.raw`^scene: (.+)$`, "Szene: $1"],
    [String.raw`^Couldn't do that: (.+)$`, (m, rest) => `Das ging nicht: ${sentences(rest)}`],
    [String.raw`^(✓ )?(?:Turn|Corner) (\S+)$`, (m, tick, name) => `${tick || ""}Kurve ${name}`],
    [String.raw`^· (Braking|Corner exit|Apex speed|Coasting|Exit speed|Line)$`, (m, area) => `· ${AREA_TITLE[area]}`],
    // Race strategy: where you'd rejoin.
    [String.raw`^About <strong>([\d.]+) s</strong> lost(?:, rejoining around <strong>P(\d+)</strong>(?: \(P(\d+) now\))?)?\.(.*)$`, (m, loss, p, now, rest) =>
      `Etwa <strong>${loss} s</strong> verloren${p ? `, Wiedereinstieg um <strong>P${p}</strong>${now ? ` (jetzt P${now})` : ""}` : ""}.${rest.replace(" Ahead: ", " Vor dir: ").replace(" Behind: ", " Hinter dir: ")}`],
    [String.raw`^From iRacing: (.+) at (.+?)\. (.*)$`, (m, car, track, rest) => `Aus iRacing: ${car} auf ${track}. ${sentences(rest)}`],
    // Session debrief.
    [String.raw`^(Race|Practice|Qualify|Lone Qualify|Open Qualify|Warmup|Offline Testing|Testing|Session) at (.+): (\d+) laps(?:, best ([\d:.]+))?\.$`, (m, type, track, laps, best) =>
      `${SESSION[type] || type} auf ${track}: ${laps} Runden${best ? `, beste ${best}` : ""}.`],
    [String.raw`^Your best (?:was ([\d.]+ s) (quicker|slower) than|matched) last time here \(([\d:.]+) on (.+)\)\.$`, (m, diff, way, time, date) =>
      diff ? `Deine beste Runde war ${diff} ${way === "quicker" ? "schneller" : "langsamer"} als beim letzten Mal hier (${time} am ${date}).` : `Du hast deine Bestzeit vom letzten Mal hier eingestellt (${time} am ${date}).`],
    [String.raw`^Most of your time goes at (.+)\.$`, (m, list) => `Die meiste Zeit verlierst du in ${list.split("; ").map(item => item.replace(/^(?:Turn|Corner) (\S+)(?: \(([^)]+)\))?, ([\d.]+) s a lap$/, (x, n, area, s) => `Kurve ${n}${area ? ` (${AREA[area] || area})` : ""}, ${s} s pro Runde`)).join("; ")}.`],
    [String.raw`^You fixed (.+) this session\.(.*)$`, (m, list, rest) => `Du hast in dieser Session ${corner(list).replace(" and ", " und ")} verbessert.${rest ? ` ${sentences(rest)}` : ""}`],
    [String.raw`^Next time: work on (?:Turn|Corner) (\S+?)(?:, ([a-z ]+))?\.(.*)$`, (m, n, area, rest) => `Nächstes Mal: arbeite an Kurve ${n}${area ? `, ${AREA[area] || area}` : ""}.${rest ? ` ${sentences(rest)}` : ""}`],
    [String.raw`^(Finished|Left the race in) P(\d+)(.*)$`, (m, how, p, rest) => `${how === "Finished" ? "Ins Ziel gekommen auf" : "Rennen verlassen auf"} P${p}${rest.replace(/^ from P(\d+)/, ", gestartet von P$1").replace(/\. (.*)$/, (x, more) => `. ${tr(more)}`)}`],
    // Coaching with corner names (Turn 5a, Corner 3).
    [String.raw`^(?:<b>)?(?:Turn|Corner) (\S+?)(?:</b>)? · (.+)$`, (m, n, area) => `${m.startsWith("<b>") ? `<b>Kurve ${n}</b>` : `Kurve ${n}`} · ${AREA_TITLE[area] || area}`],
    [String.raw`^Focus on <strong>(?:Turn|Corner) (\S+) · ([^<]+)</strong>\. (.*)$`, (m, n, area, rest) => `Konzentrier dich auf <strong>Kurve ${n} · ${AREA_TITLE[area] || area}</strong>. ${sentences(rest)}`],
    [String.raw`^You're giving away <strong>([\d.]+)s in (?:Turn|Corner) (\S+)</strong>\. (.*)$`, (m, s, n, rest) => `Du verschenkst <strong>${s}s in Kurve ${n}</strong>. ${sentences(rest)}`],
    [String.raw`^(?:Turn|Corner) (\S+?) sorted\.$`, (m, n) => `Kurve ${n} sitzt.`],
    [String.raw`^New focus: (?:Turn|Corner) (\S+?)\.$`, (m, n) => `Neue Fokuskurve: Kurve ${n}.`],
    [String.raw`^(?:Turn|Corner) (\S+?) next\.$`, (m, n) => `Als Nächstes Kurve ${n}.`],
    [String.raw`^(?:Turn|Corner) (\S+?): (.+)\.$`, (m, n, what) => {
      const NUMBERS = { two: "zwei", three: "drei", four: "vier", five: "fünf", six: "sechs", seven: "sieben", eight: "acht", nine: "neun" };
      const way = w => (w === "better" ? "besser" : "langsamer");
      const words = what.replace(/^matched your best$/, "wie deine Bestzeit").replace(/^a few hundredths (better|slower)$/, (x, w) => `ein paar Hundertstel ${way(w)}`)
        .replace(/^a tenth (better|slower)$/, (x, w) => `ein Zehntel ${way(w)}`).replace(/^(\w+) tenths (better|slower)$/, (x, t, w) => `${NUMBERS[t] || t} Zehntel ${way(w)}`);
      if (words !== what) return `Kurve ${n}: ${words}.`;
      return `Kurve ${n}: ${tr(what.charAt(0).toUpperCase() + what.slice(1) + ".").replace(/\.$/, "")}.`;
    }],
    // Spoken hazards and damage.
    [String.raw`^(Car stopped ahead|Slow car ahead|Car off ahead|Hazard ahead), (?:Turn|Corner) (\S+?)\.$`, (m, what, n) => `${tr(what + ".").replace(/\.$/, "")}, Kurve ${n}.`],
    [String.raw`^Damage, probably (front|front right|right side|rear right|rear|rear left|left side|front left)\.$`, (m, zone) =>
      `Schaden, vermutlich ${{ front: "vorne", "front right": "vorne rechts", "right side": "an der rechten Seite", "rear right": "hinten rechts", rear: "hinten", "rear left": "hinten links", "left side": "an der linken Seite", "front left": "vorne links" }[zone]}.`],
    [String.raw`^from P(\d+)(.*)$`, (m, p, rest) => `von P${p}${rest}`],
    [String.raw`^YOUR NOTES ON (.+)$`, (m, name) => `DEINE NOTIZEN ZU ${name}`],
    [String.raw`^Lap (\d+) matched your best lap in every corner\. Nice and consistent\.$`, (m, n) => `Runde ${n} war in jeder Kurve so schnell wie deine beste Runde. Schön konstant.`],
    [String.raw`^no change since (.+)$`, (m, date) => `keine Änderung seit ${date}`],
    [String.raw`^Couldn't load the lap library \((.+)\)\.$`, (m, why) => `Die Rundenbibliothek konnte nicht geladen werden (${why === "the library has no index.json yet" ? "die Bibliothek hat noch keine index.json" : why}).`],
    [String.raw`^You were faster here than on your best lap\. Whatever you did through (?:Turn|Corner) (\S+), repeat it\.$`, (m, n) => `Hier warst du schneller als in deiner besten Runde. Was immer du in Kurve ${n} gemacht hast, mach es wieder.`],
    // Names in the setup and lap pages.
    [String.raw`^(.+) \(loaded now\)$`, (m, name) => `${name} (jetzt geladen)`],
    [String.raw`^Here \((.+)\)$`, (m, track) => `Hier (${track})`],
    [String.raw`^At (.+)$`, (m, track) => `Auf ${track}`],
    [String.raw`^iRacing track map of (.+)$`, (m, track) => `iRacing-Streckenkarte von ${track}`],
    [String.raw`^Track map of (.+)$`, (m, track) => `Streckenkarte von ${track}`],
    [String.raw`^No (.+) template found in the templates folder\. Drop one here, or use Load template\.$`, (m, car) => `Keine Vorlage für ${car} im Ordner templates gefunden. Zieh eine hierher oder nutze Vorlage laden.`],
    [String.raw`^Grid Central has seen one setup for this car \((.+)\)\. Load another in iRacing's garage and it'll be here to compare\.$`, (m, name) => `Grid Central hat ein Setup für dieses Auto gesehen (${name}). Lade ein weiteres in der Garage von iRacing, dann kannst du sie hier vergleichen.`],
    [String.raw`^(.+?) <small>on (.+)</small>$`, (m, title, setup) => `${tr(title)} <small>mit ${setup}</small>`],
    [String.raw`^Heads up, you're on a qualifying setup, (.+)\. Check the fuel and the tyre pressures\.$`, (m, name) => `Achtung, du fährst ein Qualifying-Setup, ${name}. Prüf den Sprit und die Reifendrücke.`],
    [String.raw`^Driver change, (.+) is next\.$`, (m, name) => `Fahrerwechsel, als Nächstes fährt ${name}.`],
    [String.raw`^(.+) is next\.$`, (m, name) => `Als Nächstes fährt ${name}.`],
    [String.raw`^(.+) says: (.+)$`, (m, name, text) => `${name} sagt: ${text}`],
    [String.raw`^Notes on (.+?): (.+)$`, (m, name, text) => `Notizen zu ${name}: ${text}`],
    [String.raw`^Coaching against (.+?)'s ([\d:.]+)\. Your laps are now compared with it on the AI spotter page\.$`, (m, who, time) => `Training gegen die Runde von ${who} (${time}). Deine Runden werden jetzt auf der Seite KI-Spotter damit verglichen.`],
    [String.raw`^(.+?)'s lap · coaching against it$`, (m, who) => `Runde von ${who} · Training dagegen`],
    [String.raw`^Track is (getting wetter|drying), (.+) now\.$`, (m, how, level) => `Die Strecke ${how === "drying" ? "trocknet ab" : "wird nasser"}, jetzt ${tr(level)}.`],
    [String.raw`^Picked “(.+)” \((\d+)% of the sheet\)\. Shift-click adds more · Ctrl\+Z undoes\.$`, (m, name, share) => `„${layer(name)}“ ausgewählt (${share} % des Blatts). Umschalt-Klick fügt mehr hinzu · Strg+Z macht es rückgängig.`],
    [String.raw`^Added to “(.+)”\.$`, (m, name) => `Zu „${layer(name)}“ hinzugefügt.`],
    [String.raw`^That's all of “(.+)” already\. Lower the tolerance to pick less\.$`, (m, name) => `Das ist schon ganz „${layer(name)}“. Senk die Toleranz, um weniger auszuwählen.`],
    [String.raw`^(\d+) of (\d+) clean laps through (.+)$`, (m, done, need, name) => `${done} von ${need} sauberen Runden durch ${corner(name)}`],
    // Paint shop: layer names from colours, and messages with car names and file paths.
    [String.raw`^(${PAINT_COLOURS}) area(?: (\d+))?$`, (m, colour, n) => `${AREA_COLOUR[colour]} Bereich${n ? ` ${n}` : ""}`],
    [String.raw`^(${PAINT_COLOURS}) (\d+)$`, (m, colour, n) => `${tr(colour)} ${n}`],
    [String.raw`^(Hide|Show|Lock|Unlock) (.+)$`, (m, verb, name) => `${window.gridLang ? window.gridLang.t(name) : name} ${{ Hide: "ausblenden", Show: "einblenden", Lock: "sperren", Unlock: "entsperren" }[verb]}`],
    [String.raw`^Split “(.+)” into (\d+) layers\.$`, (m, name, n) => `„${layer(name)}“ in ${n} Ebenen aufgeteilt.`],
    [String.raw`^Loaded the (.+) template\.$`, (m, car) => `Vorlage für ${car} geladen.`],
    [String.raw`^Drop the (.+) template here, or use Load template\.$`, (m, car) => `Zieh die Vorlage für ${car} hierher oder nutze Vorlage laden.`],
    [String.raw`^No (.+) template found in the templates folder\.$`, (m, car) => `Im Ordner templates wurde keine Vorlage für ${car} gefunden.`],
    [String.raw`^Downloaded (car_\S+\.tga)\.$`, (m, file) => `${file} heruntergeladen.`],
    [String.raw`^Copy it into (.+)\.$`, (m, folder) => `Kopier sie nach ${folder}.`],
    [String.raw`^Copy (car_\S+\.tga) into (.+)\.$`, (m, file, folder) => `Kopier ${file} nach ${folder}.`],
    [String.raw`^Installed (paint\\.+)\.$`, (m, path) => `${path} installiert.`],
    [String.raw`^Couldn't install the paint: (.+)$`, (m, why) => `Die Lackierung konnte nicht installiert werden: ${tr(why)}`],
    [String.raw`^You picked “(.+)”\. iRacing paints go in Documents\\iRacing\\paint\. Use this folder anyway\?$`, (m, name) => `Du hast „${name}“ gewählt. iRacing-Lackierungen gehören nach Documents\\iRacing\\paint. Diesen Ordner trotzdem verwenden?`],
    [String.raw`^Replace your existing (.+) for this car\? The current paint file will be overwritten\.$`, (m, file) => `Deine vorhandene ${file} für dieses Auto ersetzen? Die aktuelle Lackierungsdatei wird überschrieben.`]
  ];
})();
